import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Daily CRM summary — Production Report","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Daily CRM summary — Production Report | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/daily-crm-summary"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Daily CRM summary — Production Report | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/daily-crm-summary"}]]},"headers":[],"relativePath":"deployment/daily-crm-summary.md","filePath":"deployment/daily-crm-summary.md","lastUpdated":1787142963000}'),d={name:"deployment/daily-crm-summary.md"};function i(s,e,n,l,c,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="daily-crm-summary-—-production-report" tabindex="-1">Daily CRM summary — Production Report <a class="header-anchor" href="#daily-crm-summary-—-production-report" aria-label="Permalink to &quot;Daily CRM summary — Production Report&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Branch</strong></td><td><code>feature/daily-crm-summary</code></td></tr><tr><td><strong>Date</strong></td><td>2026-07-23</td></tr><tr><td><strong>Status</strong></td><td><strong>Ready for GA</strong> after migrate + emails worker smoke (Critical/High audit items addressed)</td></tr><tr><td><strong>Repos</strong></td><td>SaaS-Backend, SaaS-Frontend, SaaS-Docs</td></tr></tbody></table><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>At workspace <strong>Daily Reminder Time</strong> (<code>task_reminder_time</code>, default <code>09:00</code> local), <code>crm:send-due-notifications</code> sends mail-only CRM snapshots in addition to the existing task due digest:</p><table tabindex="0"><thead><tr><th>Recipient</th><th>Email</th></tr></thead><tbody><tr><td>Workspace <strong>Owner</strong> (<code>superadmin</code>), or any user with <code>receive_all_users_daily_summary</code></td><td>User-wise <strong>team</strong> summary only (not both); roster includes only users with activity</td></tr><tr><td>Everyone else</td><td><strong>Personal</strong> summary only (skipped when no visible open CRM work)</td></tr></tbody></table><p>Counts:</p><ul><li><strong>Leads</strong> — open stages only (exclude <code>is_won</code> / <code>is_lost</code>). Personal digests omit the Leads block when the recipient has <strong>Exclude from lead assignment</strong> (<code>exclude_from_lead_auto_assign</code>); those users are emailed only when they have open tasks or scheduled meetings.</li><li><strong>Tasks</strong> — open / in_progress / waiting (exclude completed / cancelled)</li><li><strong>Meetings</strong> — scheduled only; distinct host <strong>or</strong> attendee (creator-only not counted)</li></ul><p>Team digests still show per-user Leads for full owner visibility.</p><p>Mail chrome: Branded module entitled → tenant logo/name; otherwise platform (central EloSync) logo/name via <code>BrandedMail</code>. Digests use table-based HTML templates (<code>resources/views/emails/crm/</code>) with a navy header label (<code>DAILY SUMMARY</code>), tinted metric cards, and per-user CRM cards — shared with the task due digest (<code>TASK DIGEST</code>) and department performance digest (<code>DEPT DIGEST</code>).</p><p>Aggregations run <strong>once per tenant</strong> per command tick. Meeting counts use SQL <code>COUNT(DISTINCT meeting_id)</code>.</p><hr><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Deploy Backend + Frontend + Docs from <code>feature/daily-crm-summary</code>.</li><li>Migrate:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><ul><li><code>users.receive_all_users_daily_summary</code> (default <code>false</code>)</li><li><code>daily_summary_deliveries</code> (unique <code>tenant_id, user_id, digest_date, kind</code>)</li></ul></li><li>Confirm scheduler: <code>crm:send-due-notifications</code> every 5 minutes (<code>withoutOverlapping</code>, <code>onOneServer</code>).</li><li>Confirm <code>php artisan queue:work --queue=emails</code> (and <code>queue:restart</code> after deploy).</li><li>Shared cache driver required for <code>onOneServer</code> locks.</li><li>Configure <strong>Settings → Daily Reminder Time</strong>. Owners receive the team digest automatically; optionally flag non-owner managers with <strong>Receive all-users daily summary</strong>.</li><li>Confirm <strong>Central → Branding</strong> has a platform <code>logo_path</code> uploaded so non-Branded tenant mail shows the EloSync logo (otherwise the header falls back to text app name).</li><li>Smoke: <ul><li>Past reminder time → personal mail to unflagged non-owner with open CRM work</li><li>Team mail to Owner without the flag (only users with activity)</li><li>Team mail to flagged non-owner</li><li>Excluded-from-lead-assignment user with only leads → no personal mail; with tasks → personal mail without Leads block</li><li>Without Branded: mail header uses platform logo; with Branded + tenant logo: tenant logo</li><li>HTML body shows navy header label (<code>DAILY SUMMARY</code>) and metric/user cards (not plain Markdown lines)</li><li>Second cron tick → no duplicate</li><li>Ledger <code>queued</code> → <code>sent</code>; stale <code>queued</code> (&gt;45m) reclaimable (max 5 attempts)</li><li>Watch <code>emails</code> queue depth on the first morning after deploy (Owners now get team mail whenever any member has activity)</li></ul></li><li>Keep scheduler + emails workers healthy through the local reminder window (no midnight catch-up).</li></ol><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Signal</th><th>What to watch</th></tr></thead><tbody><tr><td><code>daily_summary_deliveries.status = queued</code> older than ~45 minutes</td><td>Worker down (auto-reclaim after stale window)</td></tr><tr><td><code>attempts &gt;= 5</code> still <code>failed</code></td><td>Cap reached; investigate SMTP/queue</td></tr><tr><td><code>crm:send-due-notifications</code> duration</td><td>Should stay flat vs user count after aggregate-once fix</td></tr><tr><td>Emails queue depth</td><td>Backlog after reminder time</td></tr></tbody></table><hr><h2 id="audit-remediation-2026-07-23" tabindex="-1">Audit remediation (2026-07-23) <a class="header-anchor" href="#audit-remediation-2026-07-23" aria-label="Permalink to &quot;Audit remediation (2026-07-23)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Status</th></tr></thead><tbody><tr><td>Personal N× full-tenant scans</td><td>Fixed — <code>summarizeUsers()</code> once per tenant</td></tr><tr><td>Meeting PHP hydration</td><td>Fixed — SQL <code>COUNT(DISTINCT)</code> union</td></tr><tr><td>Stale queued / max attempts</td><td>Fixed — 45m reclaim, max 5</td></tr><tr><td>Team zero-activity noise</td><td>Fixed — <code>summarizeActiveUsers()</code></td></tr><tr><td>Deploy / database / Users API docs</td><td>Fixed</td></tr><tr><td>Pest gaps</td><td>Fixed — markSent, suspended, empty, TZ, dedupe, stale reclaim</td></tr><tr><td>Playwright flag toggle</td><td>Added <code>users.daily-summary-flag.spec.ts</code></td></tr><tr><td>RBAC duplicate Edit rows + privacy note</td><td>Fixed</td></tr></tbody></table><hr><h2 id="related-docs" tabindex="-1">Related docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related docs&quot;">​</a></h2><ul><li><a href="/user-guide/tenant-settings">Tenant settings (user)</a></li><li><a href="/user-guide/tasks">Tasks (user)</a></li><li><a href="/user-guide/tenant-rbac">Tenant RBAC (user)</a></li><li><a href="/api/tenant-v1-users">Tenant Users API</a></li><li><a href="/api/tenant-v1-notifications">Tenant notifications API</a></li><li><a href="/developer-guide/database">Database architecture</a></li><li><a href="/deployment/tasks">Tasks production</a></li><li><a href="/changelog/">Changelog</a></li></ul>',23)])])}const p=t(d,[["render",i]]);export{h as __pageData,p as default};
